\set ON_ERROR_STOP on
begin;
create function public.test_assert(ok boolean,label text) returns void language plpgsql as $$begin if ok is distinct from true then raise exception 'FAIL: %',label;end if;perform set_config('test.count',(coalesce(nullif(current_setting('test.count',true),''),'0')::int+1)::text,false);raise notice 'PASS: %',label;end$$;
create function public.test_denied(statement text,label text) returns void language plpgsql as $$declare denied boolean:=false;begin begin execute statement;exception when others then denied:=true;end;perform public.test_assert(denied,label);end$$;
